{
    return $this->options ?? 0;
}

/**
 * Toggle given options on or off.
 *
 * @param int       $options
 * @param bool|null $state
 *
 * @throws InvalidArgumentException
 *
 * @return static
 */
public function toggleOptions(int $options, ?bool $state = null): static
{
